  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'الخطأ السياقي', 'اختيار من متعدد', 'حدد الكلمة التي لا يتفق معناها مع سياق الجملة:
«يظل النحل يختار رحيق الأزهار ليصنع أطيب وأشهى شراب، كذلك الإنسان يختار مناوئه ليصنع أخلاقه»', '["النحل", "الأزهار", "أشهى", "مناوئه"]'::jsonb, 3, 'كما ينتقي النحل أطيب الرحيق ينتقي الإنسان أصفياءه الذين تُصنع بصحبتهم أخلاقه؛ لا مناوئيه أي خصومه.', NULL, 'ad260826-2026-4c00-9d00-260820260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'الخطأ السياقي', 'اختيار من متعدد', 'حدد الكلمة التي لا يتفق معناها مع سياق الجملة:
«معلومات الشبكة العنكبوتية كثيرة ومنافعها نزيرة إذا أُحسن استخدامها»', '["نزيرة", "معلومات", "منافعها", "استخدامها"]'::jsonb, 0, 'حسن الاستخدام يجعل المنافع وفيرة لا قليلة؛ فالصواب: منافعها غزيرة، والنزر هو القليل.', NULL, 'ad260826-2026-4c00-9d00-260820260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة مما يلي:', '["أحمر", "أصفر", "أزرق", "أسود"]'::jsonb, 3, 'الأحمر والأصفر والأزرق ألوان أساسية تُمزج منها بقية الألوان، وليس الأسود منها.', NULL, 'ad260826-2026-4c00-9d00-260820260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة مما يلي:', '["حقل", "سكة", "درب", "جادة"]'::jsonb, 0, 'السكة والدرب والجادة أسماء للطريق، أما الحقل فأرض تُزرع.', NULL, 'ad260826-2026-4c00-9d00-260820260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة مما يلي:', '["فالح", "ظافر", "خالد", "بسام"]'::jsonb, 3, 'فالح وظافر وخالد على وزن فاعل، أما بسام فصيغة مبالغة على وزن فعّال.', NULL, 'ad260826-2026-4c00-9d00-260820260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة مما يلي:', '["كمين", "فخ", "خديعة", "هزيمة"]'::jsonb, 3, 'الكمين والفخ والخديعة وسائل يوقع بها بالخصم، أما الهزيمة فنتيجة تلحق به.', NULL, 'ad260826-2026-4c00-9d00-260820260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة مما يلي:', '["قميص", "ثوب", "سروال", "عمامة"]'::jsonb, 3, 'القميص والثوب والسروال تُلبس على الجسد، أما العمامة فتوضع على الرأس.', NULL, 'ad260826-2026-4c00-9d00-260820260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة مما يلي:', '["غزال", "دولفين", "حوت", "سمك"]'::jsonb, 0, 'الدولفين والحوت والسمك حيوانات مائية، أما الغزال فبري.', NULL, 'ad260826-2026-4c00-9d00-260820260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'المفردة الشاذة', 'اختيار من متعدد', 'اختر المفردة الشاذة مما يلي:', '["محافظة", "قرية", "عاصمة", "إقليم"]'::jsonb, 2, 'المحافظة والقرية والإقليم تقسيمات إدارية للمكان، أما العاصمة فصفة وظيفية تُطلق على مدينة الحكم.', NULL, 'ad260826-2026-4c00-9d00-260820260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'النص يدل على:', '["نظرية", "خاطرة", "حقيقة علمية", "فرضية فيزيائية"]'::jsonb, 3, 'النص يفسر حركة الكرة بقوى مفترضة تفسيرًا فيزيائيًا قابلًا للاختبار؛ فهو فرضية فيزيائية.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82601-2026-4c00-9d00-000000000001', 'عندما نركل الكرة فإننا نعطيها قوة باتجاهين: إلى الأعلى وإلى الأمام، ثم تبتعد الكرة عنا فلا تتلقى منا مزيدًا من القوة، لكن تستمر قوتان في التأثير عليها: قوة الاحتكاك التي تبطئ سرعتها إلى الأمام، وقوة الجاذبية التي تؤثر عليها من الأعلى إلى الأسفل.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'من الذي ينصحك النص بتركه؟', '["كثير القناعة", "قليل الهمة", "قليل العزيمة", "قليل المعرفة"]'::jsonb, 0, 'الذي أُمرنا بالتكبير عليه أربعًا هو المقاوم للتغيير الراضي بالقليل، أي القانع بوضعه الذي لا يطلب المزيد.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82602-2026-4c00-9d00-000000000002', 'من كان جاهلًا فعلّمه، ومن تنقصه الإرادة فحفّزه، ومن ضل الطريق فوجّهه بتجاربك، لكن المقاوم للتغيير الراضي بالقليل فكبّر عليه أربعًا، فلا تذهب نفسك عليهم حسرات.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'من الذي يحتاج إلى تحفيز؟', '["قليل العزيمة", "قليل المعرفة", "فاقد المعنويات", "صاحب العزيمة"]'::jsonb, 0, 'النص خصص التحفيز لمن تنقصه الإرادة، أي قليل العزيمة. أما قليل المعرفة فعلاجه التعليم.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82602-2026-4c00-9d00-000000000002', 'من كان جاهلًا فعلّمه، ومن تنقصه الإرادة فحفّزه، ومن ضل الطريق فوجّهه بتجاربك، لكن المقاوم للتغيير الراضي بالقليل فكبّر عليه أربعًا، فلا تذهب نفسك عليهم حسرات.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما الصفة التي يذمها النص؟', '["الجمود", "الأنانية", "البخل", "الفوقية"]'::jsonb, 0, 'الوحيد الذي يئس منه النص هو مقاوم التغيير، ومقاومة التغيير هي الجمود.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82602-2026-4c00-9d00-000000000002', 'من كان جاهلًا فعلّمه، ومن تنقصه الإرادة فحفّزه، ومن ضل الطريق فوجّهه بتجاربك، لكن المقاوم للتغيير الراضي بالقليل فكبّر عليه أربعًا، فلا تذهب نفسك عليهم حسرات.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما الذي يحث عليه الكاتب؟', '["نشر التجارب والعلم", "الثبات على الرأي", "معاملة الناس حسب احتياجاتهم", "تحمل المسؤولية"]'::jsonb, 2, 'النص يصف لكل صنف علاجه: الجاهل بالتعليم، وناقص الإرادة بالتحفيز، والضال بالتوجيه؛ فهو يحث على معاملة كل إنسان بما يحتاجه.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82602-2026-4c00-9d00-000000000002', 'من كان جاهلًا فعلّمه، ومن تنقصه الإرادة فحفّزه، ومن ضل الطريق فوجّهه بتجاربك، لكن المقاوم للتغيير الراضي بالقليل فكبّر عليه أربعًا، فلا تذهب نفسك عليهم حسرات.', 4, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يوجه النص إلى:', '["نقل المعارف والتجارب", "تحمل الخطأ", "الثبات على الرأي", "تحمل المسؤولية"]'::jsonb, 0, 'قوله «علّمه» و«وجّهه بتجاربك» دعوة صريحة إلى نقل ما عندك من معرفة وتجربة للآخرين.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82602-2026-4c00-9d00-000000000002', 'من كان جاهلًا فعلّمه، ومن تنقصه الإرادة فحفّزه، ومن ضل الطريق فوجّهه بتجاربك، لكن المقاوم للتغيير الراضي بالقليل فكبّر عليه أربعًا، فلا تذهب نفسك عليهم حسرات.', 5, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أنسب عنوان للنص:', '["الاستفادة من الخبرات السابقة", "تحمل المسؤولية", "البحث عن الأخطاء", "التمسك بالرأي"]'::jsonb, 0, 'مدار النص على توظيف تجاربك وخبراتك في تعليم الناس وتوجيههم؛ فأنسب عنوان: الاستفادة من الخبرات السابقة.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82602-2026-4c00-9d00-000000000002', 'من كان جاهلًا فعلّمه، ومن تنقصه الإرادة فحفّزه، ومن ضل الطريق فوجّهه بتجاربك، لكن المقاوم للتغيير الراضي بالقليل فكبّر عليه أربعًا، فلا تذهب نفسك عليهم حسرات.', 6, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الضمير في (بها) يعود على:', '["الصبّار", "التفاح", "الأشياء", "المستقبل"]'::jsonb, 2, 'التقدير: كي لا يصدمك المستقبل بالأشياء التي جهلت أصلها؛ فالضمير يعود على الأشياء.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82603-2026-4c00-9d00-000000000003', 'لا تتوقع من نبتة الصبّار أن تثمر لك التفاح، حاول أن تعرف أصل الأشياء وماضيها كي لا يصدمك المستقبل بها.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'مضمون القطعة يدل على:', '["الصبر", "الفطنة", "القوة", "الحكمة"]'::jsonb, 1, 'معرفة أصول الأشياء وتوقع ما تثمره قبل وقوعه هو الفطنة التي يدعو إليها النص.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82603-2026-4c00-9d00-000000000003', 'لا تتوقع من نبتة الصبّار أن تثمر لك التفاح، حاول أن تعرف أصل الأشياء وماضيها كي لا يصدمك المستقبل بها.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'مقابل (تلوث):', '["لهو", "نقاء", "رخاء", "ارتكاب"]'::jsonb, 1, 'ضد تلوث النفوس صفاؤها ونقاؤها؛ فالمقابل: نقاء.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82604-2026-4c00-9d00-000000000004', 'لا مكان للمنعزلين في هذا العالم؛ تحاول الدول المتقدمة التقدم بالعلم. الحكومة الواعية تحاول الوصول للهدف المنشود لرخاء شعبها، والحذر الشديد من ارتكاب النقائص وتلوث النفوس وعدم صفوها.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أي مما يلي يمكن استبداله بكلمة (تلوث) دون أن يتغير المعنى؟', '["فساد", "خمول", "صفاء", "ضعف"]'::jsonb, 0, 'تلوث النفوس معناه فسادها، فالبديل الذي يحفظ المعنى هو الفساد. أما الخمول فمعناه الكسل ولا يؤدي المعنى.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82604-2026-4c00-9d00-000000000004', 'لا مكان للمنعزلين في هذا العالم؛ تحاول الدول المتقدمة التقدم بالعلم. الحكومة الواعية تحاول الوصول للهدف المنشود لرخاء شعبها، والحذر الشديد من ارتكاب النقائص وتلوث النفوس وعدم صفوها.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', '(لرخاء شعبها) تفيد:', '["التعليل", "التشبيه", "التوكيد", "التعريف"]'::jsonb, 0, 'اللام هنا لام التعليل: تسعى الحكومة للهدف المنشود من أجل رخاء شعبها.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82604-2026-4c00-9d00-000000000004', 'لا مكان للمنعزلين في هذا العالم؛ تحاول الدول المتقدمة التقدم بالعلم. الحكومة الواعية تحاول الوصول للهدف المنشود لرخاء شعبها، والحذر الشديد من ارتكاب النقائص وتلوث النفوس وعدم صفوها.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ما النتائج المترتبة على ارتكاب الذنوب وعدم صفو النفوس؟', '["الرفاهية", "ارتفاع المستوى المعيشي", "انخفاض المستوى المعيشي", "القناعة"]'::jsonb, 2, 'النص جعل الحذر من النقائص وتلوث النفوس شرطًا لبلوغ الرخاء؛ فارتكابها يفضي إلى ضده: انخفاض المستوى المعيشي.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82604-2026-4c00-9d00-000000000004', 'لا مكان للمنعزلين في هذا العالم؛ تحاول الدول المتقدمة التقدم بالعلم. الحكومة الواعية تحاول الوصول للهدف المنشود لرخاء شعبها، والحذر الشديد من ارتكاب النقائص وتلوث النفوس وعدم صفوها.', 4, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الإنسان في القرارات الكبيرة يكون:', '["مترددًا", "حاسمًا", "متسرعًا", "لا مباليًا"]'::jsonb, 0, 'النص يفتتح بأن الإنسان في حيرة من أمره في القرارات الكبيرة، والحيرة هي التردد.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82605-2026-4c00-9d00-000000000005', 'الإنسان يكون في حيرة من أمره في القرارات الكبيرة؛ يعتمد العقل تارة وأحيانًا تحكمه العاطفة. في الحياة يجب أن يكون العقل هو القبطان الذي يبحر بالسفينة ويصل بها إلى بر الأمان، والعاطفة هي الوقود الذي يحرك السفينة.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'معنى (يعتمد العقل) في النص:', '["يقدّم العقل", "يفكر بالعاطفة فقط", "يهمل العقل", "يؤجل القرار"]'::jsonb, 0, 'اعتماد العقل هو تقديمه وجعله مرجع القرار.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82605-2026-4c00-9d00-000000000005', 'الإنسان يكون في حيرة من أمره في القرارات الكبيرة؛ يعتمد العقل تارة وأحيانًا تحكمه العاطفة. في الحياة يجب أن يكون العقل هو القبطان الذي يبحر بالسفينة ويصل بها إلى بر الأمان، والعاطفة هي الوقود الذي يحرك السفينة.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يستفاد من النص:', '["العمل بالعاطفة فقط", "العمل بالعقل فقط", "الموازنة بين العقل والعاطفة", "إهمال القرارات الكبيرة"]'::jsonb, 2, 'تشبيه العقل بالقبطان والعاطفة بالوقود يجعل لكل منهما دورًا لا تسير السفينة إلا بهما معًا: قيادة عاقلة بدافع عاطفي.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82605-2026-4c00-9d00-000000000005', 'الإنسان يكون في حيرة من أمره في القرارات الكبيرة؛ يعتمد العقل تارة وأحيانًا تحكمه العاطفة. في الحياة يجب أن يكون العقل هو القبطان الذي يبحر بالسفينة ويصل بها إلى بر الأمان، والعاطفة هي الوقود الذي يحرك السفينة.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الإنسان في حياته — كما يصف النص —:', '["يعتمد العقل تارة وتحكمه العاطفة تارة", "يسمع للعقل فقط", "لا يفكر إلا بالعاطفة", "يمشي وراء آراء الآخرين"]'::jsonb, 0, 'هذا نص العبارة الافتتاحية: يعتمد العقل تارة وأحيانًا تحكمه العاطفة.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82605-2026-4c00-9d00-000000000005', 'الإنسان يكون في حيرة من أمره في القرارات الكبيرة؛ يعتمد العقل تارة وأحيانًا تحكمه العاطفة. في الحياة يجب أن يكون العقل هو القبطان الذي يبحر بالسفينة ويصل بها إلى بر الأمان، والعاطفة هي الوقود الذي يحرك السفينة.', 4, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'القائد في حياة الإنسان:', '["التجارب", "العقل", "العاطفة", "الحظ"]'::jsonb, 1, 'جعل النص العقل هو القبطان الذي يبحر بالسفينة، والقبطان هو القائد.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82605-2026-4c00-9d00-000000000005', 'الإنسان يكون في حيرة من أمره في القرارات الكبيرة؛ يعتمد العقل تارة وأحيانًا تحكمه العاطفة. في الحياة يجب أن يكون العقل هو القبطان الذي يبحر بالسفينة ويصل بها إلى بر الأمان، والعاطفة هي الوقود الذي يحرك السفينة.', 5, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الضمير في (بها) يعود على:', '["العاطفة", "السفينة", "الحياة", "القرارات"]'::jsonb, 1, 'التقدير: يبحر بالسفينة ويصل بها إلى بر الأمان؛ فالضمير يعود على السفينة.', NULL, 'ad260826-2026-4c00-9d00-260820260001', 'e1a82605-2026-4c00-9d00-000000000005', 'الإنسان يكون في حيرة من أمره في القرارات الكبيرة؛ يعتمد العقل تارة وأحيانًا تحكمه العاطفة. في الحياة يجب أن يكون العقل هو القبطان الذي يبحر بالسفينة ويصل بها إلى بر الأمان، والعاطفة هي الوقود الذي يحرك السفينة.', 6, 'active', false);
